import sys
from collections import Counter

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))

        if n == 1:
            results.append("0")
            continue

        counts = Counter(a)
        max_count = max(counts.values())

        if max_count > (n + 1) // 2:
            results.append("-1")
            continue

        distinct_tags = len(counts)

        if distinct_tags == 1:
            results.append("-1")
            continue

        num_singletons = 0
        for c in counts.values():
            if c == 1:
                num_singletons += 1

        if num_singletons >= distinct_tags:
            results.append("0")
        else:
            results.append(str(distinct_tags - 1))

    print('\n'.join(results))

if __name__ == '__main__':
    solve()
